import{_ as a,o,c as s,a2 as c}from"./chunks/framework.BXzK3EA4.js";const i="/assets/03ae69ccbf56f711.CmUm38g9.png",l="/assets/5a76eaa1334ad7f4.DESZ6nE4.png",t="/assets/afefc3f8cdbdbf9d.BVN614qf.png",r="/assets/32dec15fea0fb436.DWl_FQKJ.png",g=JSON.parse('{"title":"How to View Memory Usage and Clear Cache in Linux System","description":"","frontmatter":{"title":"How to View Memory Usage and Clear Cache in Linux System"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/how-to-view-memory-usage-and-clear-cache-in-linux-system.md","filePath":"operations-knowledge-base/operating-system/linux/how-to-view-memory-usage-and-clear-cache-in-linux-system.md","lastUpdated":1794292919000}'),n={name:"operations-knowledge-base/operating-system/linux/how-to-view-memory-usage-and-clear-cache-in-linux-system.md"};function d(m,e,u,p,h,f){return o(),s("div",null,[...e[0]||(e[0]=[c('<p>Sometimes, when a server becomes unresponsive, it may not necessarily be due to high CPU usage. It could also be caused by insufficient memory. You can refer to the following methods to check the memory usage and clear it if necessary.</p><p>1.To check the usage of physical memory and swap space on a server, you can use the command: <code>free -h</code>.</p><p><img src="'+i+'" alt=""></p><ul><li><ul><li>total: Total physical memory on the machine.</li></ul></li><li><ul><li>used: Amount of memory currently in use.</li></ul></li><li><ul><li>free: Amount of free (unused) physical memory.</li></ul></li><li><ul><li>shared: Amount of memory shared by multiple processes.</li></ul></li><li><ul><li>buff/cache: Memory used for file system buffers and cache.</li></ul></li><li><ul><li>available: Estimated amount of memory that can be allocated to applications. This is calculated as free + buffer + cache (Note: This calculation is an approximation and may have some margin of error).</li></ul></li></ul><p>2.The command to clear cache is:</p><p>echo 1 &gt; /proc/sys/vm/drop_caches //To release page cache</p><p><img src="'+l+'" alt=""></p><p>echo 2 &gt; /proc/sys/vm/drop_caches //To release dentries (directory cache) and inodes cache</p><p><img src="'+t+'" alt=""></p><p>echo 3 &gt; /proc/sys/vm/drop_caches //To release page cache, dentries (directory cache), and inodes cache</p><p><img src="'+r+'" alt=""></p><p>Note: <code>echo $?</code> returns the execution result, where a return value of 0 indicates success.</p><ul><li><ul><li><code>echo 0</code> does not release the cache.</li></ul></li><li><ul><li><code>echo 1</code> releases the page cache (clears the cache of recently accessed file pages).</li></ul></li><li><ul><li><code>echo 2</code> releases the dentries (directory cache) and inodes cache (clears the cache of directory entries and file nodes).</li></ul></li><li><ul><li><code>echo 3</code> releases all caches mentioned in options 1 and 2.</li></ul></li></ul>',13)])])}const _=a(n,[["render",d]]);export{g as __pageData,_ as default};
